def numeric_span(values):
    if not isinstance(values, list):
        raise TypeError("values must be a list")
    if any(isinstance(value, bool) or not isinstance(value, int) for value in values):
        raise TypeError("values must contain only integers")
    if not values:
        return None, None
    return min(values), max(values)


def reads_same(text):
    if not isinstance(text, str):
        raise TypeError("text must be a string")

    normalized = "".join(character.casefold() for character in text if character.isalnum())

    def compare(fragment):
        if len(fragment) < 2:
            return True
        return fragment[0] == fragment[-1] and compare(fragment[1:])

    return compare(normalized)

